//! Canonical fieldset identity and readonly form/type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset name=group><legend>Group</legend><input value=seed></fieldset></form><form id=other></form><fieldset id=external form=other></fieldset></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn fieldset_metadata_genuine_interface_and_canonical_readonly_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var fieldset=document.getElementById('fieldset'),owner=document.getElementById('owner'),C=HTMLFieldSetElement,P=C.prototype;if(!(fieldset instanceof C)||Object.getPrototypeOf(fieldset)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.prototype.toString.call(fieldset)!=='[object HTMLFieldSetElement]')throw 'genuine fieldset identity';for(var name of ['form','type']){var a=Object.getOwnPropertyDescriptor(P,name);if(!a||typeof a.get!=='function'||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get '+name||a.get.length!==0||Object.hasOwn(fieldset,name))throw 'canonical readonly metadata';}if(fieldset.form!==owner||fieldset.type!=='fieldset'||document.getElementById('external').form!==document.getElementById('other'))throw 'actual native metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal constructor';"#);}
#[test]
fn fieldset_metadata_inert_exact_owners_clone_and_adoption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),a=doc.createElementNS(html,'form'),b=doc.createElementNS(html,'form'),x=doc.createElementNS(html,'fieldset');doc.appendChild(root);root.appendChild(a);root.appendChild(b);root.appendChild(x);a.id='\ud800';b.id='\udfff';x.setAttribute('form','\ud800');if(!(x instanceof HTMLFieldSetElement)||x.form!==a||x.type!=='fieldset')throw 'exact inert metadata';x.setAttribute('form','\udfff');if(x.form!==b||x.cloneNode(false).form!==null||x.cloneNode(false).type!=='fieldset')throw 'current owner and clone';var other=new Document(),detached=other.createElementNS(html,'form');if(other.adoptNode(x)!==x)throw 'adoption identity';detached.appendChild(x);if(x.form!==detached||x.type!=='fieldset')throw 'detached ancestor after adoption';"#);}
#[test]
fn fieldset_metadata_readonly_brand_and_author_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),P=HTMLFieldSetElement.prototype,calls=0;for(var name of ['form','type']){var get=Object.getOwnPropertyDescriptor(P,name).get,expected=name==='form'?owner:'fieldset';x[name]={toString:function(){calls++;return 'bad';}};if(x[name]!==expected)throw 'readonly sloppy';var caught=false;try{(function(){'use strict';x[name]='bad';})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','fieldset')]){caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine brand';}Object.defineProperty(x,name,{value:'author',configurable:true});if(x[name]!=='author'||get.call(x)!==expected)throw 'native authority';delete x[name];if(x[name]!==expected)throw 'native restore';}if(calls)throw 'readonly conversion';"#);}

#[test]
fn fieldset_metadata_namespace_enumeration_and_saved_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),C=HTMLFieldSetElement,P=C.prototype,get=Object.getOwnPropertyDescriptor(P,'form').get,type=Object.getOwnPropertyDescriptor(P,'type').get,doc=new Document(),html='http://www.w3.org/1999/xhtml',prefixed=doc.createElementNS(html,'x:fieldset'),upper=doc.createElementNS(html,'FIELDSET');if(!(prefixed instanceof C)||prefixed.type!=='fieldset'||prefixed.form!==null)throw 'HTML namespace local brand';for(var bad of [upper,doc.createElementNS('urn:foreign','fieldset'),document.createElement('input')]){for(var read of [get,type]){var caught=false;try{read.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'distinct genuine brand';}}var formKeys=0,typeKeys=0;for(var key in x){if(key==='form')formKeys++;if(key==='type')typeKeys++;}if(formKeys!==1||typeKeys!==1)throw 'canonical inherited enumeration';delete window.HTMLFieldSetElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||Object.prototype.toString.call(x)!=='[object HTMLFieldSetElement]'||get.call(x)!==document.getElementById('owner')||type.call(x)!=='fieldset')throw 'saved canonical roots';"#);}
#[test]
fn fieldset_metadata_saved_child_origin_precedes_reads_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var x=document.getElementById('fieldset'),owner=document.getElementById('owner'),C=frame.contentWindow.HTMLFieldSetElement,P=C.prototype,get=Object.getOwnPropertyDescriptor(P,'form').get,type=Object.getOwnPropertyDescriptor(P,'type').get;if(C===HTMLFieldSetElement||get.call(x)!==owner||type.call(x)!=='fieldset')throw 'captured metadata';");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-fieldset-metadata.test/",&crate::navigation::Location::home()).unwrap());for source in ["get.call(x);","type.call(x);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}p.set_location(&crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==owner||type.call(x)!=='fieldset')throw 'captured metadata recovery';");}
#[test]
fn fieldset_metadata_current_owner_id_blocker_and_native_getter_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('external'),other=document.getElementById('other'),get=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'form').get,blocker=document.createElement('div');blocker.id='other';other.parentNode.insertBefore(blocker,other);if(x.form!==null||get.call(x)!==null)throw 'first actual id blocker';blocker.parentNode.removeChild(blocker);if(x.form!==other)throw 'current owner recovered';Object.defineProperty(x,'getAttribute',{value:function(){throw 'author attribute';},configurable:true});if(get.call(x)!==other)throw 'actual native owner authority';other.id='changed';if(get.call(x)!==null)throw 'current exact target';");}
#[test]
fn fieldset_metadata_native_refusal_and_zero_copy_or_storage_reads(){for method in [script_fieldset::FORM,script_fieldset::TYPE]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let id=if method==script_fieldset::FORM{"external"}else{"fieldset"};let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()==id)).unwrap();let other=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="other")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,3=>p.state.limits.host.string_bytes=if method==script_fieldset::FORM{0}else{7},_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_get(node_handle(n),method);let success=method==script_fieldset::FORM&&mode==3||method==script_fieldset::TYPE&&mode==4;if success{let value=result.unwrap();assert!(if method==script_fieldset::FORM{matches!(value,Value::Host(owner)if owner==node_handle(other))}else{matches!(value,Value::String(v)if v=="fieldset")});}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=1024;p.begin_job();let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_get(node_handle(n),method).unwrap();assert!(if method==script_fieldset::FORM{matches!(value,Value::Host(owner)if owner==node_handle(other))}else{matches!(value,Value::String(v)if v=="fieldset")});}}}
#[test]
fn fieldset_metadata_inert_bounded_refusal_and_fresh_recovery(){for property in ["form","type"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),owner=doc.createElementNS(html,'form'),x=doc.createElementNS(html,'fieldset');doc.appendChild(root);root.appendChild(owner);root.appendChild(x);owner.id='target';x.setAttribute('form','target');var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,childList:true});x.form;x.type;");let limit=p.state.retained_limit;let source=format!("x.{property};");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,_=>{if property=="form"{p.state.retained_limit=p.state.retained;}else{p.state.limits.host.string_bytes=7;}}};let e=p.runtime.execute(&source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=1024;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.form!==owner||x.type!=='fieldset'||watch.takeRecords().length)throw 'fresh inert metadata recovery';");}}}
#[test]
fn fieldset_metadata_preserves_actual_disabled_first_legend_control_state(){let mut d=crate::html::parse("<html><body><form id=f><fieldset id=x disabled><legend><input id=yes value=allowed></legend><input id=no value=blocked></fieldset></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let yes=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="yes")).unwrap();let no=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="no")).unwrap();assert!(!f.controls[&yes].disabled);assert!(f.controls[&no].disabled);let before=format!("{:?}",d.nodes);run(&mut d,&mut f,&mut p,"var x=document.getElementById('x'),owner=document.getElementById('f');if(x.form!==owner||x.type!=='fieldset'||owner.length!==3)throw 'fieldset metadata and listed count';");assert_eq!(format!("{:?}",d.nodes),before);assert!(!f.controls[&yes].disabled);assert!(f.controls[&no].disabled);}

#[test]
fn fieldset_metadata_inert_owner_id_author_getter_never_supplies_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),owner=doc.createElementNS(html,'form'),x=doc.createElementNS(html,'fieldset');doc.appendChild(root);root.appendChild(owner);root.appendChild(x);owner.id='target';x.setAttribute('form','target');Object.defineProperty(owner,'id',{get:function(){throw 'author owner id';},configurable:true});Object.defineProperty(x,'form',{get:function(){throw 'author owner';},configurable:true});var get=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'form').get;if(get.call(x)!==owner)throw 'exact native owner facts';delete owner.id;owner.id='changed';if(get.call(x)!==null)throw 'current native owner facts';");}

#[test]
fn fieldset_metadata_deferred_form_submit_keeps_descriptor_identity_and_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'submit'),submit=a.value;if(!a.enumerable||!a.writable||!a.configurable||typeof submit!=='function'||submit.name!=='submit'||submit.length!==0||P.submit!==submit||document.getElementById('owner').submit!==submit)throw 'native submit data descriptor';var caught=false;try{submit.call(document.body);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine form submit receiver';Object.freeze(P);if(P.submit!==submit||Object.getOwnPropertyDescriptor(P,'submit').writable||Object.getOwnPropertyDescriptor(P,'submit').configurable)throw 'stable frozen submit method';");}
